{
	Type:     schema.TypeString,
	Required: true,
	Description: "Array of IP addresses or interface names. Specifies which host or interface packets should " +
		"be sent to (IP | interface | IP%interface | IP@table[, IP | string, [..]]).",
}

{
	Type:        schema.TypeString,
	Optional:    true,
	Default:     "main",
	Description: "Routing table this route belongs to.",
}

{
	Type:     schema.TypeString,
	Required: true,
	Description: "A single IP address or range of IPs to add to address list or DNS name. You can input for " +
		"example, '192.168.0.0-192.168.1.255' and it will auto modify the typed entry to 192.168.0.0/23 on " +
		"saving.",
	DiffSuppressFunc: func(k, old, new string, d *schema.ResourceData) bool {
		if old == new {
			return true
		}

		if old == "" || new == "" {
			return false
		}

		ips := reIPv4Range.FindStringSubmatch(new)
		if len(ips) == 3 {
			s, _ := IpRangeToCIDR(ips[1], ips[2])
			return old == s
		}

		return false
	},
}

DiffSuppressFunc.expression:
func(k, old, new string, d *schema.ResourceData) bool {
	if old == new {
		return true
	}

	if old == "" || new == "" {
		return false
	}

	ips := reIPv4Range.FindStringSubmatch(new)
	if len(ips) == 3 {
		s, _ := IpRangeToCIDR(ips[1], ips[2])
		return old == s
	}

	return false
}

